#include <iostream>

class Diem {
private:
    int x;
    int y;
    int m;

public:
    void nhap(int hoanh_do, int tung_do, int ma_mau) {
        x = hoanh_do;
        y = tung_do;
        m = ma_mau;
    }

    void hien_thi() const {
        std::cout << "(" << x << ", " << y << ") - color: " << m << "\n";
    }
};

int main() {
    Diem d1;
    d1.nhap(10, 20, 1);

    // 1. Con tro tro toi doi tuong don
    Diem *p1 = &d1;
    p1->hien_thi();

    // 2. Con tro tro toi mang doi tuong
    Diem arr[2];
    arr[0].nhap(30, 40, 2);
    arr[1].nhap(50, 60, 3);
    Diem *p2 = arr;
    p2[0].hien_thi();
    (p2 + 1)->hien_thi();

    // 3. Cap phat dong voi new va giai phong voi delete
    Diem *p3 = new Diem;
    p3->nhap(70, 80, 4);
    p3->hien_thi();
    delete p3;

    return 0;
}
